{"code": "const cmd = `
$ErrorActionPreference='Stop'
$files = @(
 'D:\\lean\\tmp\\sheaf\\xif\\paper\\S1811Probe1.lean',
 'D:\\lean\\tmp\\sheaf\\xif\\paper\\S1811Probe2.lean',
 'D:\\lean\\tmp\\sheaf\\xif\\paper\\S1811Probe3.lean',
 'D:\\lean\\tmp\\sheaf\\xif\\paper\\S1811Probe4.lean',
 'D:\\lean\\tmp\\sheaf\\xif\\paper\\S1811Probe5.lean',
 'D:\\lean\\tmp\\sheaf\\xif\\paper\\S1811Probe6.lean'
)
foreach($f in $files){ if(Test-Path -LiteralPath $f){ Remove-Item -LiteralPath $f -Force; Write-Output "removed $f" } }
$src='tmp/sheaf/xif/paper/S1811SurjectiveSplitDedicatedActual.lean'
$lib='.lake/build/lib/lean/tmp/sheaf/xif/paper/S1811SurjectiveSplitDedicatedActual.olean'
$dst='tmp/sheaf/xif/paper/S1811SurjectiveSplitDedicatedActual.olean'
Copy-Item -LiteralPath $lib -Destination $dst -Force
foreach($p in @($src,$lib,$dst)){ $h=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash; $len=(Get-Item -LiteralPath $p).Length; Write-Output ("{0}`n  SHA256={1}`n  len={2}" -f $p,$h,$len) }
`;
const r = await tools.pwsh({ description: "Clean probes, copy olean, hash artifacts", command: cmd, workdir: "D:\\lean", timeoutMs: 300000 });
console.log(r.kind === 'foreground' ? "EXIT=" + r.exitCode + "\n" + r.stdout.text + r.stderr.text : JSON.stringify(r));
", "description": "Clean probes, copy olean, compute hashes"}

